const moveFeedbackVotes = `-- name: MoveFeedbackVotes :exec
WITH moved AS (
    DELETE FROM feedback_votes d WHERE d.workspace_id = $2 AND d.post_id = $3
    RETURNING d.contact_id, d.workspace_id, d.member_id, d.priority, d.created_at
)
INSERT INTO feedback_votes (post_id, contact_id, workspace_id, member_id, priority, created_at)
SELECT $1, m.contact_id, m.workspace_id, m.member_id, m.priority, m.created_at FROM moved m
ON CONFLICT (post_id, contact_id) DO NOTHING
`

type MoveFeedbackVotesParams struct {
	TargetID    ids.UUID `json:"target_id"`
	WorkspaceID ids.UUID `json:"workspace_id"`
	SourceID    ids.UUID `json:"source_id"`
}

// MoveFeedbackVotes carries a post's votes over to another, once per
// customer, and removes them from the first.
func (q *Queries) MoveFeedbackVotes(ctx context.Context, arg MoveFeedbackVotesParams) error {
	_, err := q.db.Exec(ctx, moveFeedbackVotes, arg.TargetID, arg.WorkspaceID, arg.SourceID)
	return err
}

